            { "name": "TechCrunch", "url": "https://techcrunch.com/2026/09/29/openai-reportedly-in-talks-to-raise-30b-round-at-1-4t-valuation/" },
            { "name": "CNBC", "url": "https://www.cnbc.com/2026/09/29/openai-devday-2026-live-updates.html" },
