        {
          "headline": "OpenAI ships GPT-6.1 Sol seven days after GPT-6 Sol; Artificial Analysis scores it 1 point below Astra at a fifth of the cost",
          "sources": [
            { "name": "Artificial Analysis", "url": "https://artificialanalysis.ai/articles/gpt-6-1-sol-replaces-gpt-6-sol-after-just-7-days-with-near-astra-intelligence" },
            { "name": "VentureBeat", "url": "https://venturebeat.com/technology/openais-gpt-6-1-sol-offers-astra-like-performance-at-1-5th-price-a-new-ultrafast-tier-clocks-at-300-tokens-per-second" },
            { "name": "CNBC", "url": "https://www.cnbc.com/2026/09/29/openai-devday-2026-live-updates.html" }
